const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const courses=[['Expert Sharing: Praktik Kerja yang Berdampak','Expertise','SHARE\nWHAT WORKS',0,'Live cohort','Pemula',1],['Webinar Series: Tantangan Profesional & Bisnis','Collaboration','LEARN\nTOGETHER',0,'Live cohort','Pemula',1],['Professional Workshop: Dari Insight ke Aksi','Expertise','LEARN\nBY DOING',349000,'Hybrid','Pemula',4],['Certification: Lean Six Sigma & Operational Excellence','Impact','PROVE\nYOUR SKILL',1499000,'Mandiri','Menengah',12],['In-House Training: Program Sesuai Kebutuhan Tim','Impact','BUILT FOR\nYOUR TEAM',0,'Custom','Menengah',6],['Trainer Development: Rancang Pembelajaran Dewasa','Expertise','TRAIN\nBETTER',899000,'Hybrid','Menengah',8]];
const money=n=>n?'Rp'+n.toLocaleString('id-ID'):'Gratis';let state={course:0,category:'Semua',search:'',type:'Semua',level:'Semua',sort:'relevan',tab:'Ringkasan',lesson:0,completed:JSON.parse(localStorage.getItem('xpert-completed')||'[]'),notes:localStorage.getItem('xpert-notes')||'',answer:null,quizDone:false,assessment:false,checkout:false,booked:false,chat:[],role:'peserta'};
const screens=[['home','Beranda','Nilai utama dan pintu masuk belajar.'],['catalog','Eksplorasi kelas','Pencarian, kategori, format, dan level.'],['detail','Detail program','Hasil belajar, kurikulum, mentor, biaya.'],['path','Learning path','Urutan belajar menuju target peran.'],['assessment','Skill discovery','Asesmen awal dan rekomendasi jalur.'],['mentors','Direktori mentor','Keahlian dan reservasi sesi.'],['business','ECI for Business','Pelatihan berbasis kebutuhan tim.'],['about','Tentang Xpert','Pendekatan dan standar pembelajaran.'],['login','Masuk / daftar','Akses dan orientasi peserta.'],['checkout','Pendaftaran kelas','Ringkasan biaya hingga konfirmasi.'],['dashboard','Dashboard peserta','Langkah berikutnya dan progres.'],['myclasses','Kelas saya','Kelas aktif dan riwayat belajar.'],['learn','Ruang belajar','Materi, catatan, dan progres modul.'],['quiz','Evaluasi kompetensi','Kuis, pembahasan, dan tindak lanjut.'],['assignment','Tugas & feedback','Pengumpulan hasil kerja dan rubrik.'],['schedule','Jadwal & mentoring','Agenda kelas dan sesi mentor.'],['ai','ECI Learning Assistant','Bantuan belajar dengan rujukan materi.'],['community','Komunitas','Diskusi dan berbagi hasil praktik.'],['certificates','Skill passport','Kompetensi, portofolio, sertifikat.'],['verify','Verifikasi sertifikat','Validasi ID dan bukti penyelesaian.'],['profile','Profil & preferensi','Target, waktu belajar, dan akun.'],['mentor','Workspace mentor','Review tugas dan tindak lanjut peserta.'],['admin','Dashboard admin','Performa program dan pengelolaan.'],['corporate','Dashboard perusahaan','Gap kompetensi dan progres tim.']];
const a=(route,label,cls='btn')=>`<a class="${cls}" href="#/${route}">${label}</a>`;const logo=()=>'<img class="brand" src="assets/logo.png" alt="Expert Club Indonesia">';
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function art(i){return `<div class="course-art c${i}"><small>EXPERT CLUB INDONESIA / ${courses[i][1].toUpperCase()}</small><strong>${courses[i][2].replace('\n','<br>')}</strong><small>PRACTICAL SKILLS. REAL PROGRESS.</small></div>`}
function card(i){let c=courses[i];return `<article class="card course"><a href="#/detail?course=${i}">${art(i)}<div class="course-body"><div class="row"><span class="tag">${c[4]}</span><small>${c[5]}</small></div><h3>${c[0]}</h3><div class="meta"><span>◷ ${c[6]} modul</span><span>◎ Studi kasus</span></div><div class="row line"><span class="price">${money(c[3])}</span><span class="btn white sm">Lihat kelas ↗</span></div></div></a></article>`}
function header(route){return `<div class="demo">PROTOTIPE KONSEP • Kelas, harga, nama, dan statistik adalah ilustrasi. <a href="#/presentation">Panduan presentasi ↗</a></div><header class="wrap nav"><a href="#/home">${logo()}</a><nav class="navlinks">${[['catalog','Eksplorasi kelas'],['path','Learning path'],['mentors','Mentor'],['business','Untuk perusahaan']].map(([r,l])=>a(r,l,route===r?'active':'')).join('')}</nav><div class="actions">${a('login','Masuk','btn ghost')}${a('assessment','Temukan jalurmu','btn orange')}</div></header>`}
function footer(){return `<footer class="footer"><div class="wrap"><div class="footer-grid"><div>${logo()}<p>Expertise yang dibagikan.<br>Impact yang terasa.</p><small>Konsep komunitas pembelajaran profesional.</small></div><div><b>Belajar</b>${a('catalog','Eksplorasi kelas','')}${a('path','Learning path','')}${a('mentors','Mentor','')}</div><div><b>Expert Club Indonesia</b>${a('about','Tentang Xpert','')}${a('business','Untuk perusahaan','')}${a('verify','Verifikasi sertifikat','')}</div><div><b>Ruang Anda</b>${a('dashboard','Dashboard peserta','')}${a('mentor','Workspace mentor','')}${a('admin','Dashboard admin','')}${a('presentation','Panduan presentasi','')}</div></div><div class="divider"></div><small>© 2026 Expert Club Indonesia · Prototipe presentasi, bukan layanan transaksi aktif.</small></div></footer>`}
const sideItems=[['dashboard','◫','Ringkasan'],['myclasses','▣','Kelas saya'],['path','◇','Learning path'],['schedule','▦','Jadwal belajar'],['assignment','☷','Tugas & feedback'],['ai','✧','Learning Assistant'],['community','◎','Komunitas'],['certificates','✦','Skill passport'],['profile','⚙','Profil & preferensi']];
function shell(route,body){const work=['mentor','admin','corporate'].includes(route);return `<div class="app-shell"><aside class="sidebar"><a href="#/home">${logo()}</a><div class="side-label">${work?'WORKSPACE':'LEARNING SPACE'}</div>${(work?[['admin','◫','Ringkasan admin'],['mentor','◎','Workspace mentor'],['corporate','▦','Perusahaan'],['catalog','▣','Katalog program'],['dashboard','◇','Tampilan peserta']]:sideItems).map(([r,i,l])=>`<a class="side-link ${route===r?'active':''}" href="#/${r}"><i>${i}</i>${l}</a>`).join('')}<div class="side-bottom"><div class="card" style="padding:16px;background:#f9f4ee"><small>TUMBUH SETIAP HARI</small><h4 style="margin:8px 0">Satu langkah lebih ahli.</h4>${a('assessment','Cek kompetensi →','')}</div>${a('presentation','↗ Panduan presentasi','side-link')}${a('home','← Halaman utama','side-link')}</div></aside><div><header class="app-top"><span>${work?'Expert Club Indonesia / Workspace':'Ruang belajar / '+(screens.find(s=>s[0]===route)?.[1]||'Belajar')}</span><div class="actions"><span class="tag orange">Demo</span><span class="muted">Halo, ${work?'Tim Xpert':'Nadia'}</span><span class="avatar">${work?'XI':'NP'}</span></div></header><main class="app-main">${body}</main></div></div>`}
const heading=(label,desc,action='')=>`<div class="section-title"><div><h1>${label}</h1><p>${desc}</p></div>${action}</div>`;
function home(){return `<div class="wrap"><section class="hero"><div><span class="eyebrow">EXPERTISE · COLLABORATION · IMPACT</span><h1>Tempat tumbuh<br>para <em>expert.</em></h1><p>Komunitas pembelajaran dan pengembangan profesional untuk berbagi pengetahuan, memperluas jejaring, dan mengubah pengalaman menjadi dampak.</p><div class="actions">${a('catalog','Eksplorasi kelas ↗','btn orange')}${a('assessment','Cari jalur yang tepat','btn white')}</div><div class="proof"><span><b>Belajar fleksibel</b><br>Sesuai ritmemu</span><span><b>Praktik terarah</b><br>Dengan feedback</span><span><b>Progres terukur</b><br>Bukti kompetensi</span></div></div><div class="hero-art"><img src="assets/hero.jpg" alt="Profesional belajar di ruang pelatihan modern"><div class="photo-note"><span class="stamp">✓</span><div><strong>Dari memahami, menjadi mampu.</strong><small>Materi → praktik → feedback → kompetensi</small></div></div></div></section><div class="strip"><span><b>01</b> Temukan kebutuhanmu</span><span><b>02</b> Belajar & praktik</span><span><b>03</b> Buktikan kemampuanmu</span></div></div><section class="section soft"><div class="wrap"><div class="section-title"><div><span class="eyebrow">PROGRAM ECI</span><h2>Belajar dari yang sudah menjalani.</h2><p>Berbagi praktik, mengembangkan kompetensi, dan membangun kolaborasi yang berdampak.</p></div>${a('catalog','Lihat semua kelas →','btn white')}</div><div class="chips">${['Semua','Expertise','Collaboration','Impact'].map(t=>`<a class="chip ${t==='Semua'?'active':''}" href="#/catalog?category=${encodeURIComponent(t)}">${t}</a>`).join('')}</div><div class="grid">${[0,1,2].map(card).join('')}</div></div></section><section class="section"><div class="wrap"><div class="path"><div><span class="eyebrow">LEARNING PATH</span><h2>Jangan hanya mengoleksi kelas.<br>Bangun arah yang jelas.</h2><p>Mulai dari kemampuanmu sekarang. Ikuti tahapan yang terhubung dengan target peran dan hasil kerja.</p>${a('path','Temukan learning path ↗','btn orange')}</div><div class="steps">${[['Kenali titik awalmu','Cek kebutuhan dan kompetensi awal.'],['Belajar dengan urutan yang tepat','Dari fondasi, praktik, hingga proyek akhir.'],['Tunjukkan hasilnya','Simpan bukti kompetensi di skill passport.']].map(([t,d],i)=>`<div class="step"><span class="num">${i+1}</span><div><strong>${t}</strong><p>${d}</p></div></div>`).join('')}</div></div></div></section><section class="section soft"><div class="wrap"><div class="section-title"><div><span class="eyebrow">LEBIH DARI MENONTON MATERI</span><h2>Belajar yang terasa kemajuannya.</h2></div></div><div class="grid">${[['◎','Feedback dari praktisi','Pahami apa yang sudah tepat dan apa yang perlu ditingkatkan.','mentors'],['✧','Bantuan saat kamu buntu','Temukan penjelasan dan rujukan materi bersama Learning Assistant.','ai'],['▦','Tumbuh bersama tim','Pantau skill gap, hasil asesmen, dan progres belajar karyawan.','business']].map(([i,t,d,r])=>`<div class="card"><div class="icon-block">${i}</div><h3>${t}</h3><p>${d}</p>${a(r,'Jelajahi →','')}</div>`).join('')}</div></div></section>`}
function catalog(){return `<div class="wrap"><div class="page-top"><span class="eyebrow">PROGRAM ECI</span><h1>Belajar dari yang sudah menjalani.</h1><p>Pilih ruang belajar untuk menguatkan keahlian, jejaring, dan dampak profesionalmu.</p><div class="search"><input id="course-search" aria-label="Cari kelas" placeholder="Cari kemampuan, topik, atau program…" value="${esc(state.search)}"><select id="course-sort" aria-label="Urutan kelas"><option value="relevan">Paling relevan</option><option value="price">Harga terendah</option></select></div><div class="chips">${['Semua','Expertise','Collaboration','Impact'].map(t=>`<button class="chip ${state.category===t?'active':''}" data-category="${t}">${t}</button>`).join('')}</div></div><div class="catalog"><aside class="card filter"><h3>Filter kelas</h3><h4>Format belajar</h4>${['Semua','Mandiri','Live cohort','Hybrid','Custom'].map(t=>`<label><input type="radio" name="format" value="${t}" ${state.type===t?'checked':''}>${t}</label>`).join('')}<h4>Level</h4><select id="level-filter" aria-label="Level"><option>Semua</option><option>Pemula</option><option>Menengah</option></select><div class="divider"></div><button class="btn white full" data-action="reset-filter">Reset filter</button></aside><div><p id="result-count"></p><div class="grid" id="course-results"></div></div></div></div>`}
function filterCourses(){let ids=courses.map((_,i)=>i).filter(i=>{let c=courses[i];return(state.category==='Semua'||c[1]===state.category)&&(state.type==='Semua'||c[4]===state.type)&&(state.level==='Semua'||c[5]===state.level)&&c.join(' ').toLowerCase().includes(state.search.toLowerCase())});if(state.sort==='price')ids.sort((a,b)=>courses[a][3]-courses[b][3]);$('#course-results').innerHTML=ids.length?ids.map(card).join(''):'<div class="card empty"><h3>Belum ada kelas yang cocok.</h3><p>Coba kata kunci lain atau reset filter.</p><button class="btn" data-action="reset-filter">Reset filter</button></div>';$('#result-count').textContent=ids.length+' kelas untuk langkah berikutnya';}
function detail(){let c=courses[state.course];const outcomes=state.course===0?['Membersihkan dan membaca data operasional.','Merancang sesi berbagi yang menjawab kebutuhan peserta.','Menyampaikan praktik dan rekomendasi yang bisa diterapkan.']:['Memahami fondasi '+c[1].toLowerCase()+' melalui studi kasus.','Menerapkan metode ke tantangan pekerjaan sehari-hari.','Menyusun rencana perbaikan dengan indikator hasil yang jelas.'];return `<div class="wrap section"><div class="breadcrumb">${a('catalog','Eksplorasi kelas','')} / ${c[1]}</div><div class="detail"><div><span class="tag">${c[4]} · ${c[5]}</span><h1 style="font-size:42px;margin-top:20px">${c[0]}</h1><p>Ubah pemahaman menjadi hasil kerja. Program ini menggabungkan pembelajaran terstruktur, latihan kontekstual, dan proyek yang dapat kamu tunjukkan.</p><div class="meta"><span>◷ ${c[6]} modul</span><span>◎ Proyek akhir</span><span>✦ Sertifikat penyelesaian</span></div>${art(state.course)}<div class="tabs">${['Ringkasan','Kurikulum','Mentor','FAQ'].map(t=>`<button class="tab ${state.tab===t?'active':''}" data-tab="${t}">${t}</button>`).join('')}</div>${state.tab==='Ringkasan'?`<h2>Setelah kelas ini, kamu mampu…</h2><ul class="list-clean">${outcomes.map(t=>`<li><span class="check">✓</span> ${t}</li>`).join('')}</ul><div class="callout"><b>Belajar dengan hasil yang jelas</b><br>Kamu akan mengerjakan satu studi kasus dan mendapat panduan evaluasi. Sertifikat penyelesaian berbeda dari sertifikasi profesi; skema sertifikasi khusus perlu dijelaskan pada program terkait.</div><h3>Untuk siapa kelas ini?</h3><p>Profesional yang ingin meningkatkan kemampuan praktis dan menerapkannya pada tantangan tim atau pekerjaan.</p>`:state.tab==='Kurikulum'?['Fondasi dan peta kompetensi','Mengenali masalah dalam studi kasus','Praktik terarah dan pengambilan keputusan','Proyek akhir dan evaluasi hasil'].map((t,i)=>`<details ${i===0?'open':''}><summary>0${i+1} · ${t}</summary><p>Materi inti · latihan · refleksi pembelajaran</p>${a('learn','Pratinjau materi →','')}</details>`).join(''):state.tab==='Mentor'?'<div class="card"><span class="avatar">AP</span><h3 class="spacing">Ardi Pranata</h3><p>Mentor praktisi · profil ilustrasi</p><p>Mendampingi peserta menerjemahkan konsep menjadi praktik melalui studi kasus dan feedback yang spesifik.</p></div>':['Bagaimana format belajarnya?','Kapan sertifikat diterbitkan?','Apakah ini menjamin pekerjaan?'].map((t,i)=>`<details><summary>${t}</summary><p>${['Materi mandiri dapat dipelajari sesuai ritme peserta. Untuk kelas live atau hybrid, jadwal batch ditampilkan saat pendaftaran.','Setelah materi, evaluasi, dan tugas wajib selesai sesuai kriteria program.','Tidak. Program berfokus pada pengembangan kompetensi dan bukti hasil belajar.'][i]}</p></details>`).join('')}</div><aside class="card purchase"><span class="eyebrow">INVESTASI KOMPETENSI</span><div class="price" style="font-size:32px">${money(c[3])}</div><p><small>Harga ilustrasi · satu kali pendaftaran</small></p>${a('checkout','Daftar program →','btn orange full')}<div style="margin-top:10px">${a('learn','Pratinjau materi','btn white full')}</div><ul class="list-clean"><li>✓ Materi dan latihan terstruktur</li><li>✓ Proyek untuk portofolio</li><li>✓ Forum diskusi peserta</li><li>✓ Riwayat progres belajar</li></ul><small>Butuh arahan sebelum memilih?</small>${a('assessment','Cek kebutuhan belajarmu →','side-link')}</aside></div></div>`}
function path(){return `<div class="wrap section">${heading('Kemajuan yang punya arah.','Pilih fokus pengembangan, lalu bangun expertise secara bertahap.',a('assessment','Cek skill awal','btn orange'))}<div class="path"><div><span class="eyebrow">FEATURED LEARNING PATH</span><h2>Professional Expert</h2><p>Dari membaca angka hingga menghasilkan insight yang membantu keputusan bisnis.</p><span class="tag">4 tahap · sekitar 8 minggu · Pemula</span><div class="spacing">${a('detail?course=0','Mulai dari fondasi →','btn orange')}</div></div><div class="steps">${['Kenali expertise yang ingin dibagikan','Belajar dari praktik profesional','Bangun kolaborasi lintas peran','Ubah insight menjadi dampak nyata'].map((t,i)=>`<a href="#/detail?course=0" class="step"><span class="num">${i+1}</span><div><strong>${t}</strong><p>${[ 'Petakan pengalaman dan kebutuhan','Uji metode lewat studi kasus','Dapatkan feedback dari komunitas','Tunjukkan hasil praktikmu'][i]}</p></div></a>`).join('')}</div></div><div class="grid spacing">${[['Program Facilitator',1],['People & Team Leader',2],['Project Coordinator',5]].map(([t,i])=>`<div class="card"><span class="eyebrow">CAREER DIRECTION</span><h3>${t}</h3><p>Fondasi → praktik → evaluasi → proyek.</p>${a('detail?course='+i,'Lihat langkah belajar ↗','btn white')}</div>`).join('')}</div></div>`}
function assessment(){return `<div class="wrap section" style="max-width:850px">${heading('Mulai dari dirimu.','Kenali kebutuhan belajar sebelum memilih kelas.')}<div class="card">${!state.assessment?`<span class="tag">Skill discovery · 3 pertanyaan</span><form id="assessment-form"><h3 class="spacing">Apa target utamamu?</h3>${['Berbagi expertise dengan lebih terarah','Membangun kolaborasi profesional','Menciptakan impact bagi tim dan organisasi'].map((t,i)=>`<label class="option"><input required type="radio" name="goal" value="${i}">${t}</label>`).join('')}<div class="two spacing"><div class="form-field"><label>Pengalaman saat ini</label><select name="experience"><option>Baru mulai</option><option>Sudah memahami dasar</option><option>Sudah berpengalaman</option></select></div><div class="form-field"><label>Waktu belajar per minggu</label><select name="time"><option>2–3 jam</option><option>4–5 jam</option><option>Lebih dari 5 jam</option></select></div></div><button class="btn orange" type="submit">Lihat rekomendasi jalur →</button></form>`:`<span class="tag green">Rekomendasi awal siap</span><h2 class="spacing">${courses[state.course][0]}</h2><p>Mulai dari fondasi, lanjutkan dengan latihan, lalu evaluasi lewat proyek. Rekomendasi ini berdasarkan pilihanmu, bukan tes kompetensi terstandar.</p><div class="callout">Rencana awal: 2 sesi belajar dan 1 latihan setiap minggu. Sesuaikan kecepatan dengan kebutuhanmu.</div><div class="actions">${a('detail?course='+state.course,'Lihat program rekomendasi','btn orange')}<button class="btn white" data-action="retake">Ulangi discovery</button></div>`}</div></div>`}
function dashboard(){return `${heading('Selamat datang kembali, Nadia 👋','Sedikit progres hari ini, satu langkah lebih dekat dengan tujuanmu.',a('catalog','Eksplorasi kelas','btn white'))}<div class="dashboard"><div><div class="welcome"><span class="eyebrow">NEXT STEP · EXPERTISE</span><h2>Praktik baik tumbuh<br>dari kolaborasi yang tepat.</h2><p>Lanjutkan modul Expert Sharing. Kali ini, ubah pengalaman kerja menjadi praktik yang bisa dibagikan.</p>${a('learn','Lanjutkan belajar →','btn orange')}</div><div class="stats">${[['3','Kelas aktif'],['6,5 jam','Belajar bulan ini'],['2','Skill terbukti'],['4 hari','Belajar konsisten']].map(([n,l])=>`<div class="stat"><strong>${n}</strong><small>${l}</small></div>`).join('')}</div><div class="section-title"><h2>Lanjutkan perjalananmu</h2>${a('myclasses','Semua kelas →','')}</div>${learnCard()}<div class="card spacing"><div class="row"><h3>Peta kompetensimu</h3>${a('certificates','Skill passport ↗','')}</div>${[['Expertise',65],['Collaboration',40],['Impact',25]].map(([s,n])=>`<div class="row"><span>${s}</span><small>${n}%</small></div><div class="progress"><span style="width:${n}%"></span></div>`).join('')}<small>Indikator demo dari latihan dan evaluasi, bukan pengukuran psikometrik.</small></div></div><aside><div class="card"><div class="row"><h3>Agenda terdekat</h3><span>▦</span></div><small>SEPTEMBER 2026</small><div class="week">${['S 21','S 22','R 23','K 24','J 25'].map((d,i)=>`<div class="day ${i===2?'active':''}">${d.split(' ')[0]}<br><b>${d.split(' ')[1]}</b></div>`).join('')}</div><div class="schedule-item"><span class="tag orange">Live class</span><h4 class="spacing">ECI Webinar Series</h4><p>23 Sep · 19.00–20.30 WIB</p>${a('schedule','Lihat agenda →','')}</div><div class="schedule-item"><h4>Project: praktik berdampak</h4><p>Tenggat 25 Sep · 23.59 WIB</p>${a('assignment','Lihat tugas →','')}</div></div><div class="card spacing"><span class="eyebrow">LEARNING ASSISTANT</span><h3>Butuh sudut pandang lain?</h3><p>Tanyakan bagian materi yang belum kamu pahami.</p>${a('ai','Tanya ECI Learning Assistant ✧','btn white full')}</div></aside></div>`}
function learnCard(){return `<div class="card learn-card">${art(0)}<div><span class="tag">Expertise</span><h3 style="margin-top:10px">${courses[0][0]}</h3><div class="progress"><span style="width:${Math.round(state.completed.length/4*100)}%"></span></div><div class="row"><small>${state.completed.length} dari 4 materi demo selesai</small>${a('learn','Lanjutkan →','btn sm')}</div></div></div>`}
const lessons=['Memetakan kebutuhan profesional','Belajar dari praktik nyata','Membangun kolaborasi yang produktif','Mengubah insight menjadi dampak'];
function learn(){return `<div class="breadcrumb">${a('myclasses','Kelas saya','')} / Expert Sharing / Modul ${state.lesson+1}</div><div class="player-grid"><div><div class="video"><div><small>ECI PROGRAM / EXPERT SHARING</small><h2 class="spacing">${lessons[state.lesson]}</h2></div><div class="row"><button class="play" data-action="play" aria-label="Buka pratinjau materi">▶</button><small>Pratinjau materi interaktif · ${state.lesson+1}/4</small></div></div><div class="tabs"><button class="tab active" data-learntab="overview">Ringkasan</button><button class="tab" data-learntab="notes">Catatan saya</button><button class="tab" data-learntab="resources">Bahan praktik</button></div><div id="learn-content"><h2>${lessons[state.lesson]}</h2><p>${['Sebelum merancang program, tentukan kebutuhan peserta dan hasil yang ingin dicapai. Tujuan yang jelas membuat materi, praktik, dan evaluasi lebih terarah.','Petakan pengalaman, konteks, dan tantangan peserta sebelum memilih metode. Catat insight agar bisa dibagikan dan dikembangkan bersama.','Gunakan format belajar yang sesuai: webinar untuk berbagi insight, workshop untuk praktik, dan mentoring untuk pendalaman. Pilih metode yang membantu tujuan tercapai.','Pisahkan insight, aksi, dan dampak. Setiap rekomendasi perlu pemilik, indikator keberhasilan, dan waktu evaluasi.'][state.lesson]}</p><div class="callout"><b>Latihan singkat</b><br>Tulis satu kebutuhan belajar dari pekerjaanmu. Tentukan peserta, hasil yang diharapkan, dan cara mengukur dampaknya.</div></div><div class="row line"><small>Progres tersimpan di perangkat ini.</small><button class="btn orange" data-action="complete">${state.completed.includes(state.lesson)?'Materi selesai ✓':'Tandai selesai & lanjut →'}</button></div></div><aside><div class="card" style="padding:0;overflow:hidden"><div style="padding:20px"><h3>Isi kelas</h3><small>${state.completed.length}/4 materi demo selesai</small><div class="progress"><span style="width:${state.completed.length*25}%"></span></div></div>${lessons.map((t,i)=>`<button class="lesson ${i===state.lesson?'active':''} ${state.completed.includes(i)?'complete':''}" data-lesson="${i}"><span>${state.completed.includes(i)?'✓':'0'+(i+1)} &nbsp; ${t}</span><small>8 m</small></button>`).join('')}<div style="padding:20px">${a('quiz','Evaluasi kompetensi →','btn white full')}</div></div><div class="card spacing"><h3>Belum cukup jelas?</h3><p>Dapatkan contoh lain dan rujukan materi.</p>${a('ai','Buka Learning Assistant','btn white full')}</div></aside></div>`}
function quiz(){return `${heading('Cek pemahamanmu.','Expert Sharing · Evaluasi demo · 1 pertanyaan')}<div class="card" style="max-width:850px">${!state.quizDone?`<span class="tag">Pertanyaan 1 dari 1</span><h2 class="spacing">Pertanyaan mana yang paling siap dianalisis?</h2><form id="quiz-form">${['Bagaimana bisnis kita?','Mengapa semua pelanggan tidak membeli?','Bagaimana perubahan omzet per kanal selama 3 bulan terakhir?'].map((t,i)=>`<label class="option"><input type="radio" name="answer" value="${i}" required>${t}</label>`).join('')}<button type="submit" class="btn orange spacing">Periksa jawaban</button></form>`:`<span class="tag ${state.answer===2?'green':'orange'}">${state.answer===2?'Jawaban tepat':'Mari pelajari kembali'}</span><div class="big-number">${state.answer===2?'100':'0'}<small>/100</small></div><h2>${state.answer===2?'Fondasi yang baik. Lanjutkan ke praktik.':'Pertanyaan yang baik perlu ruang lingkup jelas.'}</h2><p>“Bagaimana perubahan omzet per kanal selama 3 bulan terakhir?” memiliki metrik (omzet), dimensi (kanal), dan periode (3 bulan). Ini membuat analisis terarah.</p><div class="callout">Rujukan: Modul 1 · Merumuskan pertanyaan bisnis.</div><div class="actions">${a('assignment','Kerjakan proyek →','btn orange')}<button class="btn white" data-action="retry-quiz">Coba kembali</button></div>`}</div>`}
function assignment(){return `${heading('Buktikan lewat hasil kerja.','Proyek akhir · Expert Sharing untuk Keputusan Bisnis')}<div class="two"><div><div class="card"><span class="tag orange">Tenggat 25 September 2026</span><h2 class="spacing">Professional Workshop</h2><p>Susun dashboard yang membantu manajer menentukan kanal penjualan yang perlu diprioritaskan.</p><h4>Yang perlu dikumpulkan</h4><ol><li>Pertanyaan bisnis dan asumsi.</li><li>Dashboard dengan tiga metrik utama.</li><li>Ringkasan insight dan dua rekomendasi.</li></ol><h4>Rubrik penilaian</h4>${[['Kualitas data','30%'],['Ketepatan analisis','30%'],['Kejelasan visual','20%'],['Rekomendasi','20%']].map(([t,n])=>`<div class="row line"><span>${t}</span><b>${n}</b></div>`).join('')}</div><div class="card spacing"><h3>Feedback mentor · contoh</h3><p>“Visualisasi sudah mudah dibaca. Tambahkan pembanding periode agar perubahan omzet memiliki konteks. Hubungkan rekomendasi dengan metrik yang kamu temukan.”</p><small>Ardi Pranata · Pada contoh tugas sebelumnya</small></div></div><div class="card" style="align-self:start"><h3>Kumpulkan pekerjaanmu</h3><form id="assignment-form"><div class="form-field"><label>Link hasil kerja</label><input name="url" type="url" placeholder="https://…" required></div><div class="form-field"><label>Catatan untuk mentor</label><textarea name="note" placeholder="Jelaskan pendekatan dan bagian yang ingin diberi feedback." required></textarea></div><button class="btn orange full">Kumpulkan tugas demo</button></form><div id="submission-status" class="callout ${localStorage.getItem('xpert-submission')?'':'hide'}">✓ Tugas tersimpan sebagai simulasi di perangkat ini. Belum dikirim ke mentor.</div><small>Link hanya disimpan di perangkat ini. Tidak ada pengiriman ke server.</small></div></div>`}
function schedule(){return `${heading('Rencanakan waktu untuk tumbuh.','Agenda belajar · September 2026')}<div class="two"><div class="card"><div class="row"><h3>September 2026</h3><span class="tag">WIB</span></div><div class="calendar">${['Sen','Sel','Rab','Kam','Jum','Sab','Min'].map(d=>`<b>${d}</b>`).join('')}${Array.from({length:35},(_,i)=>{let d=i;return `<div class="${[23,25,28].includes(d)?'event':''}">${d>0&&d<=30?d:''}${d===23?'<small>Live class</small>':d===25?'<small>Deadline</small>':d===28?'<small>Mentoring</small>':''}</div>`}).join('')}</div></div><div><div class="card"><span class="tag orange">Live class</span><h3 class="spacing">ECI Webinar Series</h3><p>23 September · 19.00–20.30 WIB<br>Latihan menyampaikan insight bersama mentor.</p><button class="btn" data-action="remind">Simpan pengingat demo</button></div><div class="card spacing"><h3>Mentoring 1-on-1</h3><p>28 September · 16.00–16.30 WIB<br>Review proyek dan diskusi arah belajar.</p>${a('mentors','Pilih mentor & jadwal','btn white')}</div></div></div>`}
function ai(){return `${heading('Pahami lebih dalam, satu pertanyaan lagi.','ECI Learning Assistant · Simulasi jawaban berbasis skenario')}<div class="two"><div class="card"><div class="row"><h3>✧ ECI Learning Assistant</h3><span class="tag">Konteks: Expert Sharing</span></div><div class="chat" id="chat"><div class="message">Halo, Nadia. Bagian mana yang ingin kamu pahami? Coba tanyakan pertanyaan bisnis atau pemilihan grafik.</div>${state.chat.map(m=>`<div class="message ${m.user?'user':''}">${esc(m.text)}</div>`).join('')}</div><div class="chips"><button class="chip" data-prompt="Bagaimana merancang program yang berdampak?">Pertanyaan bisnis</button><button class="chip" data-prompt="Kapan memakai workshop atau mentoring?">Memilih grafik</button></div><form id="chat-form" class="search"><input name="q" aria-label="Pertanyaan" placeholder="Tanyakan tentang materi…" required><button class="btn">Kirim ↗</button></form><small>Demo menggunakan jawaban terprogram. Integrasi AI dan pencarian materi diperlukan pada aplikasi produksi.</small></div><div class="card" style="align-self:start"><span class="eyebrow">BELAJAR DENGAN RUJUKAN</span><h3>Jawaban yang bisa ditelusuri.</h3><p>Rancangan assistant membantu menjelaskan materi, memberi contoh, dan mengarahkanmu kembali ke sumber belajar.</p><div class="callout">Untuk pertanyaan di luar materi, assistant mengarahkan peserta ke mentor tanpa mengarang jawaban.</div>${a('learn','Kembali ke materi →','btn white')}</div></div>`}
function mentors(){return `<div class="wrap section">${heading('Belajar bersama orang yang berpraktik.','Temukan pendamping untuk membahas tantangan dan hasil belajarmu.')}<div class="grid">${[['AP','Ardi Pranata','Expert Sharing','Praktik berbagi pengetahuan'],['MR','Maya Rahayu','Collaboration','Komunikasi & fasilitasi komunitas'],['DS','Dimas Santoso','Impact','Pemetaan proses & perbaikan kerja']].map(([init,n,t,d],i)=>`<div class="card"><div class="avatar" style="width:64px;height:64px;font-size:20px">${init}</div><h3 class="spacing">${n}</h3><span class="tag">${t}</span><p class="spacing">${d}</p><small>Profil mentor ilustrasi</small><div class="divider"></div><label for="slot-${i}">Pilih jadwal · WIB</label><select id="slot-${i}"><option>28 Sep · 16.00–16.30</option><option>29 Sep · 19.00–19.30</option></select><button class="btn full spacing" data-book="${n}" data-slot="${i}">Reservasi sesi demo</button></div>`).join('')}</div><div id="booking-status" class="callout hide"></div></div>`}
function certificates(){return `${heading('Kemampuanmu, dengan buktinya.','Skill passport · Nadia Putri',a('verify','Verifikasi sertifikat','btn white'))}<div class="stats">${[['2','Kompetensi terbukti'],['1','Proyek portofolio'],['1','Sertifikat demo'],['3','Skill dikembangkan']].map(([n,t])=>`<div class="stat"><strong>${n}</strong><small>${t}</small></div>`).join('')}</div><div class="two"><div class="card"><h3>Bukti kompetensi</h3>${[['Trainer Development','Selesai · Evaluasi 88/100'],['Problem framing','Selesai · Evaluasi 90/100'],['Impact & evaluation','Dalam pengembangan']].map(([t,d])=>`<div class="row line"><div><b>${t}</b><p><small>${d}</small></p></div><span class="check">✦</span></div>`).join('')}<h3 class="spacing">Portofolio</h3><p>Professional Workshop · Proyek contoh</p>${a('assignment','Lihat proyek & feedback →','')}</div><div class="certificate">${logo()}<small>CERTIFICATE OF COMPLETION · DEMO</small><h2 class="spacing">Sertifikat Penyelesaian</h2><p>Diberikan kepada</p><h3>Nadia Putri</h3><p>Trainer Development untuk Profesional</p><small>ID: XPT-DEMO-2026-001<br>Contoh desain · bukan sertifikat resmi</small><div class="spacing">${a('verify','Periksa sertifikat →','btn white')}</div></div></div>`}
function verify(){return `<div class="wrap section" style="max-width:820px">${heading('Verifikasi bukti belajar.','Periksa identitas sertifikat dan program yang diselesaikan.')}<div class="card"><form id="verify-form"><label for="cert-id">ID sertifikat</label><div class="search"><input id="cert-id" name="id" placeholder="XPT-DEMO-2026-001" required><button class="btn orange">Verifikasi</button></div></form><p class="spacing"><small>Gunakan XPT-DEMO-2026-001 untuk mencoba simulasi.</small></p><div id="verify-result"></div></div></div>`}
function checkout(){let c=courses[state.course];return `<div class="wrap section" style="max-width:1050px">${heading(state.checkout?'Pendaftaran demo berhasil.':'Satu langkah menuju skill baru.',state.checkout?'Kelas siap dijelajahi melalui ruang belajar demo.':'Pendaftaran program · Semua nominal adalah ilustrasi.')}${state.checkout?`<div class="card empty"><span class="big-number check">✓</span><h2>${c[0]}</h2><p>Tidak ada pembayaran atau pendaftaran sungguhan yang diproses.</p>${a('dashboard','Masuk ruang belajar →','btn orange')}</div>`:`<div class="two"><div class="card"><h3>Informasi peserta</h3><form id="checkout-form"><div class="form-field"><label>Nama lengkap</label><input name="name" placeholder="Nama peserta" required></div><div class="form-field"><label>Email</label><input name="email" type="email" placeholder="nama@email.com" required></div><label class="option"><input type="radio" name="payment" checked>Virtual account · simulasi</label><label class="option"><input type="radio" name="payment">QRIS · simulasi</label><label class="option"><input type="checkbox" required>Saya memahami bahwa ini simulasi pendaftaran.</label><button class="btn orange full">Konfirmasi pendaftaran demo</button></form></div><div class="card" style="align-self:start">${art(state.course)}<h3 class="spacing">${c[0]}</h3><div class="row line"><span>Biaya program</span><b>${money(c[3])}</b></div><div class="row line spacing"><span>Total ilustrasi</span><span class="price">${money(c[3])}</span></div><div class="callout">Tidak meminta nomor kartu atau data pembayaran. Pajak dan kebijakan harga final ditentukan saat implementasi.</div></div></div>`}</div>`}
function login(){return `<div class="auth"><div class="auth-art"><span class="eyebrow">WELCOME TO EXPERT CLUB INDONESIA</span><h2>Setiap ahli<br>pernah memulai.</h2><p>Tumbuh bersama komunitas Expert Club Indonesia.</p><div class="steps spacing"><div>✓ Belajar sesuai targetmu</div><div>✓ Praktik dengan arahan</div><div>✓ Lihat progres yang nyata</div></div></div><div class="auth-form"><h2>Selamat datang.</h2><p>Jelajahi ruang belajar melalui akun demo.</p><form id="login-form"><div class="form-field"><label>Nama panggilan</label><input name="name" placeholder="Nama kamu" required></div><div class="form-field"><label>Tujuan belajar</label><select><option>Meningkatkan kemampuan kerja</option><option>Mempersiapkan peran baru</option><option>Memimpin tim</option></select></div><button class="btn orange full">Masuk ke ruang belajar demo →</button></form><div class="divider"></div><small>Prototipe ini tidak menggunakan autentikasi. Akun, verifikasi email, dan pemulihan password termasuk cakupan implementasi produksi.</small></div></div>`}
function community(){return `${heading('Belajar lebih jauh, bersama.','Ruang diskusi untuk bertanya, berbagi, dan saling memberi perspektif.')}<div class="two"><div><div class="card"><span class="tag">Diskusi kelas</span><h3 class="spacing">Grafik seperti apa untuk membandingkan performa cabang?</h3><p>Saya punya data omzet 6 cabang selama satu kuartal. Lebih tepat pakai batang atau garis?</p><small>Rani · Expert Sharing · Postingan contoh</small><div class="callout">Mentor: gunakan batang untuk membandingkan total antarcabang. Gunakan garis jika fokusmu melihat tren per bulan.</div></div><div id="posts"></div></div><div class="card" style="align-self:start"><h3>Mulai diskusi</h3><form id="post-form"><div class="form-field"><label>Topik</label><input name="title" required placeholder="Apa yang ingin kamu bahas?"></div><div class="form-field"><label>Pertanyaan atau pengalaman</label><textarea name="body" required></textarea></div><button class="btn orange">Posting di demo</button></form><p class="spacing"><small>Posting hanya muncul di sesi demo ini.</small></p></div></div>`}
function profile(){return `${heading('Belajar dengan caramu.','Atur target dan kebiasaan belajar yang realistis.')}<div class="card" style="max-width:850px"><div class="row"><div class="avatar">NP</div><span class="tag">Profil demo</span></div><form id="profile-form" class="spacing"><div class="two"><div class="form-field"><label>Nama lengkap</label><input name="name" value="${esc(localStorage.getItem('xpert-name')||'Nadia Putri')}" required></div><div class="form-field"><label>Target peran</label><select name="role"><option>Professional Expert</option><option>Program Facilitator</option><option>Community Builder</option></select></div><div class="form-field"><label>Target belajar mingguan</label><select name="hours"><option>3 jam per minggu</option><option>5 jam per minggu</option></select></div><div class="form-field"><label>Waktu pilihan</label><select><option>Malam hari</option><option>Pagi hari</option><option>Akhir pekan</option></select></div></div><button class="btn orange">Simpan preferensi</button></form></div>`}
function business(){return `<div class="wrap"><section class="hero"><div><span class="eyebrow">ECI FOR BUSINESS</span><h1>Tim berkembang.<br><em>Bisnis bergerak.</em></h1><p>Hubungkan program pelatihan dengan kebutuhan peran, hasil asesmen, dan perubahan kemampuan tim.</p>${a('corporate','Jelajahi dashboard perusahaan ↗','btn orange')}</div><div class="card"><span class="eyebrow">TEAM COMPETENCY OVERVIEW · DEMO</span><h2>Dari kehadiran ke kemampuan.</h2>${[['Expertise',72],['Collaboration',64],['Impact',48]].map(([t,n])=>`<div class="row spacing"><b>${t}</b><span>${n}%</span></div><div class="progress"><span style="width:${n}%"></span></div>`).join('')}<div class="callout">Identifikasi gap → tetapkan program → evaluasi hasil.</div></div></section><div class="grid">${[['01','Petakan kebutuhan','Tentukan kompetensi per peran sebelum menugaskan kelas.'],['02','Jalankan program','Gabungkan materi mandiri, kelas live, dan praktik.'],['03','Tinjau dampak','Bandingkan asesmen awal–akhir dan hasil proyek.']].map(([n,t,d])=>`<div class="card"><span class="eyebrow">${n}</span><h3>${t}</h3><p>${d}</p></div>`).join('')}</div><section class="section"><div class="card"><h2>Rancang program untuk tim Anda.</h2><form id="business-form" class="two"><div class="form-field"><label>Nama perusahaan</label><input required placeholder="Perusahaan Anda"></div><div class="form-field"><label>Kebutuhan utama</label><select><option>Expertise & digital capability</option><option>Trainer & leadership development</option><option>Operational excellence</option></select></div><div class="form-field"><label>Jumlah peserta</label><select><option>10–25 orang</option><option>26–100 orang</option><option>Lebih dari 100 orang</option></select></div><div><label>&nbsp;</label><button class="btn orange">Buat ringkasan kebutuhan demo</button></div></form><div id="business-result"></div></div></section></div>`}
function about(){return `<div class="wrap section"><span class="eyebrow">TENTANG EXPERT CLUB INDONESIA</span><h1>Pengetahuan menjadi bernilai<br>saat dibagikan dan diterapkan.</h1><p style="max-width:720px">Expert Club Indonesia dirancang sebagai komunitas belajar dan pengembangan profesional: membantu peserta mengenali kebutuhan, membangun kemampuan, dan menunjukkan bukti hasil belajarnya.</p><div class="grid spacing">${[['Relevan dengan pekerjaan','Materi dimulai dari situasi dan keputusan yang dihadapi profesional.'],['Terarah, bukan berlebihan','Jalur belajar memudahkan peserta menentukan langkah berikutnya.'],['Terukur dan transparan','Hasil belajar dijelaskan melalui rubrik, feedback, dan bukti praktik.']].map(([t,d])=>`<div class="card"><h3>${t}</h3><p>${d}</p></div>`).join('')}</div><div class="banner spacing"><h3>Standar yang ingin dibangun</h3><p>Kurikulum dengan hasil belajar eksplisit, profil mentor terverifikasi, materi berkala, aksesibilitas, dan kebijakan sertifikat yang jelas. Ini merupakan usulan standar untuk platform baru.</p></div></div>`}
function admin(){return `${heading('Gambaran program, dalam satu tempat.','Operasional Expert Club Indonesia · September 2026 · Data demo',a('catalog','Lihat katalog','btn white'))}<div class="stats">${[['248','Peserta aktif'],['76%','Penyelesaian program'],['18','Tugas perlu direview'],['6','Program berjalan']].map(([n,t])=>`<div class="stat"><small>${t}</small><strong>${n}</strong></div>`).join('')}</div><div class="two"><div class="card"><h3>Aktivitas belajar mingguan</h3><p>Peserta yang menyelesaikan minimal satu materi.</p><div class="chart">${[48,72,60,90,80,110,130].map((n,i)=>`<div class="bar" style="height:${n}px"><span>M${i+1}</span></div>`).join('')}</div></div><div class="card"><h3>Perlu perhatian</h3><div class="schedule-item"><b>12 peserta belum aktif 7 hari</b><p>Periksa kendala belajar sebelum mengirim pengingat.</p><button class="btn white sm" data-action="review-risk">Lihat daftar peserta</button></div><div class="schedule-item"><b>18 tugas menunggu feedback</b><p>Prioritaskan tugas yang masuk lebih dari 2 hari.</p>${a('mentor','Buka workspace mentor →','')}</div></div></div><div class="card spacing"><div class="row"><h3>Pengelolaan program</h3><button class="btn sm" data-action="new-program">+ Buat draft program</button></div><div id="program-draft"></div><div class="table-wrap"><table><thead><tr><th>Program</th><th>Format</th><th>Peserta</th><th>Penyelesaian</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${courses.slice(0,4).map((c,i)=>`<tr><td><b>${c[0]}</b></td><td>${c[4]}</td><td>${[86,64,58,40][i]}</td><td>${[78,71,82,69][i]}%</td><td><span class="tag green">Aktif</span></td><td>${a('detail?course='+i,'Tinjau ↗','')}</td></tr>`).join('')}</tbody></table></div></div>`}
function mentor(){return `${heading('Feedback yang membuat peserta maju.','Workspace mentor · Ardi Pranata · Data demo')}<div class="stats">${[['3','Kelas diampu'],['18','Tugas menunggu'],['4','Sesi minggu ini'],['1,2 hari','Rata-rata review']].map(([n,t])=>`<div class="stat"><small>${t}</small><strong>${n}</strong></div>`).join('')}</div><div class="two"><div class="card"><h3>Antrean review</h3>${['Nadia Putri','Bima Saputra','Rani Wulandari'].map((n,i)=>`<div class="row line"><div><b>${n}</b><p><small>Professional Workshop · ${i+1} hari lalu</small></p></div><button class="btn white sm" data-review="${n}">Review</button></div>`).join('')}<div class="callout">Pilih peserta untuk memberi penilaian dan feedback simulasi.</div></div><div class="card"><h3 id="review-title">Review: Nadia Putri</h3><form id="review-form"><div class="form-field"><label>Nilai akhir (0–100)</label><input type="number" min="0" max="100" value="85" required></div><div class="form-field"><label>Feedback yang dapat ditindaklanjuti</label><textarea required placeholder="Apa yang sudah baik? Apa langkah perbaikan berikutnya?"></textarea></div><div class="form-field"><label>Keputusan</label><select><option>Lulus</option><option>Perlu revisi</option></select></div><button class="btn orange">Simpan review demo</button></form></div></div>`}
function corporate(){return `${heading('Bangun kemampuan tim secara terarah.','Workspace perusahaan · PT Nusa Karya (ilustrasi)', '<button class="btn white" data-action="export-report">Unduh laporan CSV</button>')}<div class="stats">${[['42','Peserta tim'],['78%','Progres rata-rata'],['+22 poin','Asesmen awal–akhir'],['8','Perlu pendampingan']].map(([n,t])=>`<div class="stat"><small>${t}</small><strong>${n}</strong></div>`).join('')}</div><div class="two"><div class="card"><h3>Kompetensi vs target</h3>${[['Expertise',72,85],['Collaboration',64,80],['Impact',48,75]].map(([t,n,k])=>`<div class="row spacing"><b>${t}</b><small>${n} / target ${k}</small></div><div class="progress"><span style="width:${n}%"></span></div>`).join('')}</div><div class="card"><h3>Rekomendasi tindak lanjut</h3><p>Gap terbesar ada pada kolaborasi. Prioritaskan workshop fasilitasi, mentoring, dan praktik lintas tim.</p>${a('detail?course=2','Tinjau Professional Workshop →','btn white')}<div class="callout">Perbandingan asesmen adalah contoh data, bukan bukti dampak bisnis atau hubungan sebab-akibat.</div></div></div><div class="card spacing"><h3>Perkembangan peserta</h3><div class="table-wrap"><table><thead><tr><th>Peserta</th><th>Tim</th><th>Program</th><th>Progres</th><th>Asesmen</th><th>Tindak lanjut</th></tr></thead><tbody>${[['Nadia Putri','Business','Expert Sharing','75%','62 → 86','Lanjut praktik'],['Bima Saputra','Operations','Professional Workshop','90%','58 → 82','Review proyek'],['Rani Wulandari','People','Trainer Development','32%','55 → —','Pendampingan']].map(row=>`<tr>${row.map((c,i)=>`<td>${i===5?'<span class="tag">'+c+'</span>':c}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`}
function presentation(){return `<div class="wrap section"><span class="eyebrow">EXPERT CLUB INDONESIA / PRODUCT CONCEPT</span><h1>Dari katalog pelatihan<br>ke perjalanan kompetensi.</h1><p style="max-width:760px">Panduan presentasi: jelaskan kebutuhan peserta, demonstrasikan perjalanan belajar, lalu tunjukkan bagaimana mentor dan perusahaan mengukur hasilnya.</p><div class="actions">${a('home','Mulai demo beranda ↗','btn orange')}${a('dashboard','Langsung ke ruang belajar','btn white')}</div><section class="section"><h2>Apa yang diperbaiki?</h2><div class="table-wrap"><table><thead><tr><th>Observasi pada referensi publik / screenshot</th><th>Usulan Xpert</th><th>Manfaat yang dituju</th></tr></thead><tbody><tr><td>Katalog dan sertifikat menjadi fokus utama</td><td>Discovery + learning path + outcome kelas</td><td>Peserta lebih mudah menentukan pilihan</td></tr><tr><td>Informasi program pada kartu relatif singkat</td><td>Level, format, praktik, kurikulum, biaya jelas</td><td>Mengurangi ketidakpastian sebelum mendaftar</td></tr><tr><td>Perjalanan sesudah daftar belum terlihat dari screenshot</td><td>Ruang belajar, tugas, feedback, skill passport</td><td>Langkah berikutnya selalu jelas</td></tr><tr><td>Layanan karier masih ditampilkan “segera hadir”</td><td>Prioritaskan bukti kompetensi dan mentoring</td><td>Fokus pada manfaat yang dapat dibangun dahulu</td></tr></tbody></table></div><div class="callout">Audit terbatas pada screenshot yang diberikan dan halaman publik. Fitur di balik login platform lama belum diperiksa; tidak diasumsikan tidak tersedia. BWA menginspirasi eksplorasi kelas dan roadmap, bukan konten atau identitas visual.</div><p><a href="https://pusattrainingdankarir.com/" target="_blank" rel="noreferrer">Referensi: Pusat Training dan Karir ↗</a> · <a href="https://buildwithangga.com/" target="_blank" rel="noreferrer">BuildWithAngga ↗</a></p></section><h2>Peta ${screens.length} layar</h2><div class="presentation-grid">${screens.map(([r,t,d],i)=>`<a class="screen-link" href="#/${r}"><span class="screen-number">${String(i+1).padStart(2,'0')} / ${i<10?'DISCOVER':i<21?'LEARN & GROW':'MANAGE'}</span><b>${t} ↗</b><small>${d}</small></a>`).join('')}</div><section class="section"><h2>Prioritas implementasi</h2><div class="grid">${[['Tahap 1 · Fondasi','Katalog, detail, akun peserta, pembayaran, ruang belajar, progres, kuis, sertifikat, dan admin.','Ukuran: konversi daftar, aktivasi belajar, penyelesaian.'],['Tahap 2 · Kualitas belajar','Learning path, asesmen awal, tugas, rubrik, feedback mentor, agenda, dan komunitas.','Ukuran: ketepatan review, progres kompetensi, retensi.'],['Tahap 3 · Skalabilitas','Assistant berbasis sumber, dashboard B2B, penugasan tim, dan analitik lanjutan.','Ukuran: adopsi tim, kualitas jawaban, hasil asesmen.']].map(([t,d,m])=>`<div class="card"><h3>${t}</h3><p>${d}</p><small>${m}</small></div>`).join('')}</div><div class="banner spacing"><h3>Batas prototipe</h3><p>Interaksi, formulir, pencarian, kuis, catatan, dan progres disimulasikan di browser. Belum ada backend, pembayaran, autentikasi, video streaming, pengiriman email, atau AI sungguhan. Konten kelas, profil mentor, perusahaan, harga, dan statistik adalah contoh untuk presentasi.</p></div></section></div>`}
function reveal(){const items=document.querySelectorAll('.hero > div,.section-title,.card,.path,.step,.stat,.schedule-item,.presentation-grid > *,.player-grid > *,.auth > *,.banner,.callout');items.forEach((el,i)=>{el.classList.add('reveal');el.style.setProperty('--reveal-delay',Math.min(i%8,7)*55+'ms')});if(!('IntersectionObserver' in window)){items.forEach(el=>el.classList.add('is-visible'));return}const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target)}}),{threshold:.12,rootMargin:'0px 0px -8%'});items.forEach(el=>observer.observe(el))}
function render(){let [route,query]=(location.hash.slice(2)||'home').split('?');let params=new URLSearchParams(query);if(params.has('course'))state.course=Math.max(0,Math.min(5,Number(params.get('course'))||0));if(params.has('category'))state.category=params.get('category');const pages={home,catalog,detail,path,assessment,dashboard,learn,quiz,assignment,schedule,ai,mentors,certificates,verify,checkout,login,community,profile,business,about,admin,mentor,corporate,presentation,myclasses:()=>heading('Tersimpan untuk perjalananmu.','Kelas aktif dan progres belajar.',a('catalog','Tambah kelas','btn orange'))+learnCard()+`<div class="two spacing">${[2,4].map(card).join('')}</div>`};if(!pages[route])route='home';document.title=(screens.find(s=>s[0]===route)?.[1]||'Panduan presentasi')+' — Expert Club Indonesia';const internal=['dashboard','myclasses','learn','quiz','assignment','schedule','ai','community','certificates','profile','admin','mentor','corporate'].includes(route);const app=$('#app');app.classList.remove('page-ready','page-leaving');app.innerHTML=internal?shell(route,pages[route]()):header(route)+pages[route]()+footer();if(route==='catalog'){filterCourses();$('#level-filter').value=state.level;$('#course-sort').value=state.sort}window.scrollTo({top:0,behavior:'smooth'});requestAnimationFrame(()=>{app.classList.add('page-ready');reveal()})}
window.addEventListener('hashchange',render);
document.addEventListener('click',e=>{let link=e.target.closest('a[href^="#/"]');if(!link||e.defaultPrevented)return;let target=link.getAttribute('href');if(target===location.hash)return;e.preventDefault();let app=$('#app');app.classList.remove('page-ready');app.classList.add('page-leaving');setTimeout(()=>{location.hash=target},180)});
document.addEventListener('input',e=>{if(e.target.id==='course-search'){state.search=e.target.value;filterCourses()}if(e.target.id==='notes'){state.notes=e.target.value;localStorage.setItem('xpert-notes',state.notes)}});
document.addEventListener('change',e=>{if(e.target.name==='format'){state.type=e.target.value;filterCourses()}if(e.target.id==='level-filter'){state.level=e.target.value;filterCourses()}if(e.target.id==='course-sort'){state.sort=e.target.value;filterCourses()}});
function ask(q){state.chat.push({user:true,text:q});let text=/grafik|visual|batang/i.test(q)?'Gunakan grafik batang untuk membandingkan kategori, misalnya omzet per cabang. Gunakan grafik garis untuk tren waktu. Mulai dari pertanyaan yang ingin dijawab. Rujukan: Modul 3 · Memilih visualisasi yang tepat.':/pertanyaan|bisnis|metrik/i.test(q)?'Tentukan metrik, dimensi, dan periode. Contoh: “Bagaimana omzet per kanal selama tiga bulan terakhir?” Lalu tentukan keputusan yang akan dibuat dari hasilnya. Rujukan: Modul 1 · Merumuskan pertanyaan bisnis.':'Pertanyaan ini belum tercakup dalam skenario demo. Buka materi terkait atau diskusikan dengan mentor. Pada versi produksi, jawaban perlu bersumber dari materi yang telah disetujui.';state.chat.push({text});render();$('#chat').scrollTop=$('#chat').scrollHeight}
document.addEventListener('click',e=>{let el=e.target.closest('button');if(!el)return;if(el.dataset.category){state.category=el.dataset.category;render()}if(el.dataset.tab){state.tab=el.dataset.tab;render()}if(el.dataset.lesson){state.lesson=Number(el.dataset.lesson);render()}if(el.dataset.learntab){document.querySelectorAll('[data-learntab]').forEach(b=>b.classList.toggle('active',b===el));$('#learn-content').innerHTML=el.dataset.learntab==='notes'?`<label for="notes">Catatan pribadi</label><textarea id="notes" placeholder="Tulis hal penting dari materi…">${esc(state.notes)}</textarea><p><small>Otomatis tersimpan di perangkat ini.</small></p>`:el.dataset.learntab==='resources'?'<h3>Bahan praktik</h3><p>Data praktik contoh untuk latihan pengambilan keputusan.</p><button class="btn white" data-action="download-data">Unduh dataset CSV</button><div class="spacing"></div>':'<h3>'+lessons[state.lesson]+'</h3><p>Identifikasi kebutuhan, peserta, dan hasil sebelum mulai merancang program. Hubungkan praktik dengan dampak yang ingin dibuat.</p><div class="callout">Praktik: tentukan satu kebutuhan belajar dari pekerjaanmu.</div>'}if(el.dataset.prompt)ask(el.dataset.prompt);if(el.dataset.book){state.booked=true;$('#booking-status').classList.remove('hide');$('#booking-status').textContent='✓ Reservasi demo: '+el.dataset.book+' · '+$('#slot-'+el.dataset.slot).value+' WIB. Tidak ada undangan yang dikirim.';el.textContent='Reservasi dipilih ✓'}if(el.dataset.review){$('#review-title').textContent='Review: '+el.dataset.review;toast('Peserta dipilih untuk review')}switch(el.dataset.action){case'reset-filter':state.category=state.type=state.level='Semua';state.search='';render();break;case'retake':state.assessment=false;render();break;case'complete':if(!state.completed.includes(state.lesson))state.completed.push(state.lesson);localStorage.setItem('xpert-completed',JSON.stringify(state.completed));if(state.lesson<3)state.lesson++;else toast('Semua materi demo selesai. Lanjutkan evaluasi.');render();break;case'play':el.closest('.video').innerHTML='<div><small>PRATINJAU MATERI · DEMO TANPA VIDEO</small><h2 class="spacing">Dari kebutuhan umum ke program yang terukur.</h2><p style="color:#c9d5e9">“Apa yang perlu dikembangkan?” → “Program apa yang membantu tim berkolaborasi lebih baik?”</p></div><small>Peserta: tim · Metode: workshop · Dampak: praktik diterapkan</small>';break;case'retry-quiz':state.quizDone=false;render();break;case'remind':el.textContent='Pengingat tersimpan ✓';toast('Pengingat demo ditandai. Tidak ada notifikasi terjadwal.');break;case'download-data':download('xpert-data-latihan.csv','Bulan,Kanal,Omzet\nJuli,Online,42000000\nJuli,Retail,38000000\nAgustus,Online,47000000\nAgustus,Retail,36000000\nSeptember,Online,52000000\nSeptember,Retail,40000000');break;case'export-report':download('xpert-laporan-tim-demo.csv','Peserta,Tim,Progres,AsesmenAwal,AsesmenAkhir\nNadia Putri,Business,75%,62,86\nBima Saputra,Operations,90%,58,82\nRani Wulandari,People,32%,55,');break;case'review-risk':el.closest('.schedule-item').innerHTML='<b>Peserta perlu pendampingan · contoh</b><p>Rani Wulandari · Trainer Development · tidak aktif 8 hari<br>Fajar Rahman · Expert Sharing · tidak aktif 10 hari</p><small>Tindak lanjut: tanyakan kendala dan sesuaikan rencana belajar.</small>';break;case'new-program':$('#program-draft').innerHTML='<form id="draft-form" class="search spacing"><input name="title" required placeholder="Nama program baru" aria-label="Nama program"><button class="btn">Simpan draft demo</button></form>';break}});
document.addEventListener('submit',e=>{e.preventDefault();let f=e.target,d=new FormData(f);switch(f.id){case'assessment-form':state.course=Number(d.get('goal'));state.assessment=true;render();break;case'quiz-form':state.answer=Number(d.get('answer'));state.quizDone=true;render();break;case'checkout-form':state.checkout=true;render();break;case'login-form':localStorage.setItem('xpert-name',d.get('name'));location.hash='/dashboard';break;case'assignment-form':localStorage.setItem('xpert-submission',JSON.stringify({url:d.get('url'),note:d.get('note')}));$('#submission-status').classList.remove('hide');toast('Tugas demo tersimpan');break;case'chat-form':ask(d.get('q'));break;case'verify-form':$('#verify-result').innerHTML=String(d.get('id')).trim().toUpperCase()==='XPT-DEMO-2026-001'?'<div class="callout"><span class="tag green">Sertifikat demo ditemukan</span><h3 class="spacing">Nadia Putri</h3><p>Trainer Development untuk Profesional<br>ID: XPT-DEMO-2026-001</p><small>Catatan: record contoh, bukan validasi sertifikat resmi.</small></div>':'<div class="callout"><b>ID tidak ditemukan.</b><br>Periksa penulisan ID. Untuk demo gunakan XPT-DEMO-2026-001.</div>';break;case'post-form':$('#posts').insertAdjacentHTML('afterbegin',`<div class="card spacing"><span class="tag">Posting sesi demo</span><h3 class="spacing">${esc(d.get('title'))}</h3><p>${esc(d.get('body'))}</p><small>Nadia · Baru saja</small></div>`);f.reset();toast('Diskusi ditambahkan ke sesi demo');break;case'profile-form':localStorage.setItem('xpert-name',d.get('name'));localStorage.setItem('xpert-preferences',JSON.stringify(Object.fromEntries(d)));toast('Preferensi tersimpan di perangkat ini');break;case'business-form':$('#business-result').innerHTML='<div class="callout">✓ Ringkasan kebutuhan siap untuk diskusi: asesmen awal → program terarah → evaluasi akhir. Formulir demo ini tidak mengirim data.</div>';break;case'review-form':toast('Review demo tersimpan. Belum dikirim ke peserta.');f.querySelector('button').textContent='Review tersimpan ✓';break;case'draft-form':$('#program-draft').innerHTML='<div class="callout">Draft demo “'+esc(d.get('title'))+'” siap. Tahap berikutnya: susun hasil belajar, kurikulum, dan aturan evaluasi.</div>';break}});
function download(name,txt){let u=URL.createObjectURL(new Blob(['\uFEFF'+txt],{type:'text/csv;charset=utf-8'})),el=document.createElement('a');el.href=u;el.download=name;el.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}render();
